(function(root){'use strict';const extra={"en":{"module":"A2 · Everyday life","pilot":"A2 · 30 lessons · Grammar, listening, vocabulary and speaking.","moduleDone":"All A2 lessons complete","a2l1":"What are your roommates like?","a2l2":"My friends","a2l3":"My family","a2l4":"Helping at home","a2l5":"The city where I live","a2l6":"Giving directions","a2l7":"Shopping for clothes","a2l8":"My hobbies","a2l9":"A birthday party","a2l10":"Talking about films","a2l11":"Checking into a hotel","a2l12":"Renting a car","a2l13":"New York transport","a2l14":"Living in Paris","a2l15":"Paris and New York: cost of living","a2l16":"Paris sightseeing","a2l17":"American bars","a2l18":"Future plans","a2rule1_1":"With be, put be before the subject. With other Present Simple verbs, use do/does + subject + base verb.","a2rule1_2":"What is someone like? asks about personality. What does someone like? asks about preferences.","a2rule1_3":"Use Present Simple for routines and Present Continuous for an action happening now.","a2g1":"Ask about people and distinguish routines from actions now.","a2feedback1_1":"Invert be: Are they friendly?","a2feedback1_2":"Mia is singular: does + base verb.","a2feedback1_3":"Be like asks about personality; does like asks about preferences.","a2feedback1_4":"A routine with she needs studies.","a2feedback1_5":"Present Continuous uses is + -ing.","a2feedback1_6":"Question word + does + subject + base verb.","a2rule2_1":"A subject question asks who does the action. In affirmative simple-tense subject questions, do not add do/does/did.","a2rule2_2":"An object question keeps the subject and uses do/does/did + base verb in the simple tenses.","a2rule2_3":"In everyday questions, the preposition commonly goes at the end.","a2g2":"Ask who does an action and who receives it.","a2feedback2_1":"Who is the subject, so use listens without does.","a2feedback2_2":"Lisa remains the subject; does takes listen.","a2feedback2_3":"Go cycling with someone: put with at the end.","a2feedback2_4":"Who is the subject and takes the singular form loves.","a2feedback2_5":"After did use the base verb meet.","a2feedback2_6":"Keep about at the end of the object question.","a2rule3_1":"Subject pronouns go before the verb; object pronouns go after a verb or preposition.","a2rule3_2":"A possessive adjective needs a noun. A possessive pronoun replaces the noun phrase.","a2rule3_3":"Whose asks about ownership. Its shows possession; it’s means it is or it has.","a2g3":"Use subject, object and possessive forms to describe family.","a2feedback3_1":"The person receiving help uses the object form me.","a2feedback3_2":"Her goes before the noun notebook.","a2feedback3_3":"Mine replaces my notebook.","a2feedback3_4":"After to use the object form them.","a2feedback3_5":"Possessive its has no apostrophe.","a2feedback3_6":"Whose asks who owns the phone.","a2rule4_1":"Must and have to express obligation. Must often reflects the speaker’s rule; have to often refers to a requirement. These uses overlap.","a2rule4_2":"Mustn’t means forbidden. Don’t have to means optional. Use had to for past obligation.","a2rule4_3":"Learn do/make as combinations: do the dishes, do homework, make the bed, make a list.","a2g4":"Discuss household rules, optional tasks and do/make collocations.","a2feedback4_1":"Mustn’t expresses prohibition.","a2feedback4_2":"Don’t have to means it is not necessary.","a2feedback4_3":"Make the bed is the fixed combination.","a2feedback4_4":"Past obligation uses had to.","a2feedback4_5":"With she use has to.","a2feedback4_6":"Questions with have to use do + subject + have to.","a2rule5_1":"Who identifies people; which or that identifies things. Keep the relative word when it is the subject.","a2rule5_2":"Where describes a place where an action happens. Do not add commas in these defining clauses.","a2rule5_3":"Many goes with plural countable nouns; much goes with uncountable nouns. A lot of works with both.","a2g5":"Describe places with relative clauses and quantity words.","a2feedback5_1":"Where gives the location of running.","a2feedback5_2":"Who identifies a person and is the clause subject.","a2feedback5_3":"Traffic is uncountable: much.","a2feedback5_4":"Both that and which are valid object relative pronouns here.","a2feedback5_5":"Parks is plural and countable.","a2feedback5_6":"Where introduces a location, with no defining-clause comma.","a2rule6_1":"Along follows a street or path; across goes from one side to the other; through goes inside an area.","a2rule6_2":"Use to for a destination and into for entering. Go home/there without to. Use go by bus or on foot.","a2rule6_3":"Use go + -ing for activities, go for a walk, and go on a trip.","a2g6":"Give directions and use movement and go patterns.","a2feedback6_1":"Along follows a line such as a street.","a2feedback6_2":"Into emphasizes entering.","a2feedback6_3":"Go + -ing describes this activity.","a2feedback6_4":"Home is an adverb; no to is needed.","a2feedback6_5":"Use by bus without an article for the travel method.","a2feedback6_6":"An imperative starts with the base verb turn.","a2rule7_1":"Something is common in affirmative sentences and offers. Anything is common in questions and negatives. Put adjectives after these words.","a2rule7_2":"Too + adjective means excessive. Enough goes before a noun but after an adjective.","a2rule7_3":"Try on is separable. A pronoun object goes between the verb and particle.","a2g7":"Shop for clothes using indefinite pronouns, too/enough and try on.","a2feedback7_1":"A thing is something; the adjective warm follows it.","a2feedback7_2":"Before an adjective use too.","a2feedback7_3":"With a separable phrasal verb, put it in the middle.","a2feedback7_4":"Enough follows the adjective big.","a2feedback7_5":"After didn’t use anything, avoiding a standard-English double negative.","a2feedback7_6":"Anything takes its adjective after it.","a2rule8_1":"Use -ing after enjoy and after prepositions. Like can take -ing or to + verb in many contexts.","a2rule8_2":"Want, plan and would like usually take to + base verb. Use to + verb for the purpose of an action.","a2rule8_3":"After a modal, use the base verb without to. An -ing activity can also be the subject.","a2g8":"Talk about hobbies with gerunds and infinitives.","a2feedback8_1":"Enjoy takes an -ing form.","a2feedback8_2":"Want takes a to-infinitive.","a2feedback8_3":"After can use the base verb.","a2feedback8_4":"After the preposition in use -ing.","a2feedback8_5":"An activity used as a subject can take -ing.","a2feedback8_6":"To learn gives the purpose of reading.","a2rule9_1":"Past Simple describes finished actions. Use a past form in statements, but did/didn’t + base verb in questions and negatives.","a2rule9_2":"Because introduces a reason clause. Because of takes a noun phrase. So introduces a result.","a2rule9_3":"Although introduces a contrast clause. However normally follows a full stop or semicolon, with a comma after it.","a2g9":"Tell a past story and connect reasons, contrasts and results.","a2feedback9_1":"Last month is a finished past time: went.","a2feedback9_2":"After didn’t use stay.","a2feedback9_3":"The traffic is a noun phrase, so use because of.","a2feedback9_4":"Although introduces the contrast clause.","a2feedback9_5":"After did use the base verb.","a2feedback9_6":"So connects a cause to its result. A comma before so separates these clauses.","a2rule10_1":"Use simple forms for stative meanings such as like, know, need and prefer.","a2rule10_2":"Some verbs change meaning: think as an opinion is simple; thinking about a decision is an activity.","a2rule10_3":"Have for possession is normally simple. Have for an activity can be continuous.","a2g10":"Describe film preferences and distinguish states from actions.","a2feedback10_1":"Opinion think normally takes the simple form.","a2feedback10_2":"Have as an activity can be continuous.","a2feedback10_3":"Stative like uses Present Simple; she takes doesn’t.","a2feedback10_4":"Knowledge is a state: I know.","a2feedback10_5":"Considering a choice is an activity: thinking about.","a2feedback10_6":"Prefer expresses a preference and normally uses the simple form.","a2rule11_1":"Can/Could + subject + base verb makes a request. Could is often more polite here, not past time. Would like takes a noun or to + verb.","a2rule11_2":"Give and show allow receiver + thing, or thing + to + receiver. With two pronouns, prefer thing + to + receiver.","a2rule11_3":"Explain takes thing + to + person; do not use explain me. Buy takes for for the beneficiary.","a2g11":"Make polite requests at a hotel and give something to someone.","a2feedback11_1":"Could takes subject + base verb, without do or to.","a2feedback11_2":"Put the thing pronoun it before to + receiver me.","a2feedback11_3":"Explain does not use the ordinary double-object pattern.","a2feedback11_4":"Would like + to-infinitive describes what you want to do.","a2feedback11_5":"Buy uses for for the person who benefits.","a2feedback11_6":"Show allows receiver me before the thing the room.","a2rule12_1":"Present Continuous can describe a future arrangement. Going to + base verb describes an intention and can also describe an arranged plan.","a2rule12_2":"By + time means no later than that time. At + time gives a point in time.","a2rule12_3":"On time means punctual according to a schedule. In time means early enough for something. Both can describe the same arrival.","a2g12":"Talk about travel plans, deadlines and arriving in time.","a2feedback12_1":"Present Continuous uses am + meeting; tomorrow gives future context.","a2feedback12_2":"By gives the latest allowed time, not an exact appointment.","a2feedback12_3":"In time means soon enough; on time means punctual.","a2feedback12_4":"With I use am going to + base verb.","a2feedback12_5":"With we use are + driving for this future plan.","a2feedback12_6":"In time to + verb means early enough to do the action.","a2rule13_1":"Use -er with many short adjectives and more with longer adjectives. Compare with than; good becomes better and bad becomes worse.","a2rule13_2":"Use the superlative to compare one option with a whole group: the best, the fastest, the most comfortable. Do not combine more with -er or most with -est.","a2rule13_3":"Most + noun means a general majority. Most of + these/the/my or an object pronoun names a specific group; the most can express a superlative.","a2g13":"Compare transport options and distinguish most from most of.","a2feedback13_1":"Use the comparative cheaper with than.","a2feedback13_2":"Good has the irregular superlative the best.","a2feedback13_3":"These identifies a specific group, so use most of.","a2feedback13_4":"Bad becomes worse in the comparative.","a2feedback13_5":"Before an object pronoun use most of us.","a2feedback13_6":"Comparative adjective + than introduces the second option.","a2rule14_1":"Present Simple describes routines. Present Continuous describes actions now and temporary situations around now.","a2rule14_2":"Get + adjective describes a change. Use getting for a change in progress.","a2rule14_3":"No longer normally goes before the main verb, or after be. Anymore/any longer goes at the end of a negative clause; any more is also valid for time, especially in British English.","a2g14":"Describe routines, current changes and things that have stopped.","a2feedback14_1":"A routine uses Present Simple; Emma takes writes.","a2feedback14_2":"Present Continuous uses is + looking.","a2feedback14_3":"No longer goes before feel and already gives negative meaning.","a2feedback14_4":"Get + adjective describes a change; double the t in getting.","a2feedback14_5":"These end-position expressions mean the situation has stopped; temporal any more is also valid.","a2feedback14_6":"Is getting + comparative describes an ongoing improvement.","a2rule15_1":"Present Perfect uses have/has + past participle. It connects the past to now, including experiences and situations still true now.","a2rule15_2":"Use Past Simple for finished past periods. Use Present Perfect for a situation that started earlier and continues now; do not add yesterday or a finished past date.","a2rule15_3":"For introduces a duration; since introduces a starting point. A comparative can be strengthened with much or a lot.","a2g15":"Contrast finished past time with situations continuing now.","a2feedback15_1":"The situation continues now: have lived.","a2feedback15_2":"This period is finished, so use Past Simple.","a2feedback15_3":"Much can strengthen a comparative; do not add more to cheaper.","a2feedback15_4":"Six months is a duration: for.","a2feedback15_5":"Monday is a starting point: since.","a2feedback15_6":"Have + past participle lived forms Present Perfect; for introduces a duration.","a2rule16_1":"Use should + base verb for advice. Shouldn’t means advice against an action; do not add to or -s.","a2rule16_2":"Questions use Should + subject + base verb, without do. I think you should and I don’t think you should give a personal recommendation.","a2rule16_3":"A real condition can use if + Present Simple with an imperative or can in the result. Use a comma when the if-clause comes first.","a2g16":"Give sightseeing advice with should and conditional suggestions.","a2feedback16_1":"After should use the base verb wear.","a2feedback16_2":"Should comes before the subject without do or to.","a2feedback16_3":"This real future condition uses Present Simple after if.","a2feedback16_4":"Shouldn’t or should not gives advice against rushing.","a2feedback16_5":"Can + base verb expresses what is possible under this condition.","a2feedback16_6":"Advice uses subject + should + base verb.","a2rule17_1":"Use to + base verb for the purpose of an action, and for + noun for an item or activity. For + -ing can describe an object’s function.","a2rule17_2":"Must expresses a strong requirement; should gives advice. Both take the base verb without to and keep the same form with every subject.","a2rule17_3":"Mustn’t means forbidden. Don’t/doesn’t have to means optional, not forbidden. Have to uses do/does in questions.","a2g17":"Explain purpose and distinguish advice, rules and optional actions.","a2feedback17_1":"Use to + base verb for the purpose of meeting.","a2feedback17_2":"For takes the noun phrase a chat.","a2feedback17_3":"Don’t have to means there is no obligation.","a2feedback17_4":"For + -ing describes the function of the screen.","a2feedback17_5":"Questions with have to use do + subject + have to.","a2feedback17_6":"Must takes the base verb without to.","a2rule18_1":"Use am/is/are + going to + base verb for an intention. Put not after be, and move be before the subject in a question.","a2rule18_2":"Will often expresses an instant decision or offer. Going to can express an earlier intention; Present Continuous can describe an arrangement. These future forms sometimes overlap.","a2rule18_3":"Want, plan and would like take to + base verb. Planning describes an intention or current planning; it does not by itself prove that a trip is booked.","a2g18":"Describe intentions, wishes and decisions about the future.","a2feedback18_1":"With I use am going to + base verb.","a2feedback18_2":"I’ll help you is an offer made at the moment of speaking.","a2feedback18_3":"Would like takes a to-infinitive.","a2feedback18_4":"With she use is going to.","a2feedback18_5":"Plan takes to + base verb; planning alone does not confirm a booking.","a2feedback18_6":"Future intention: subject + am + going to + base verb.","a2l19":"New Year’s resolutions","a2rule19_1":"Going to describes an intention. For the negative, put not after am/is/are, before going to.","a2rule19_2":"A few goes with plural countable nouns; a little goes with uncountable nouns. They mean some, while few/little without a often suggests not enough.","a2rule19_3":"Less means a smaller amount with an uncountable noun; fewer means a smaller number with plural countable nouns. Too much/too many means an excessive amount or number.","a2g19":"Describe resolutions and manageable amounts of practice.","a2feedback19_1":"Put not after am, before going to.","a2feedback19_2":"Goals is a plural countable noun: a few.","a2feedback19_3":"Time is uncountable: less.","a2feedback19_4":"Time is uncountable: a little time.","a2feedback19_5":"Distractions is plural and countable: too many.","a2feedback19_6":"Not follows am; going to is followed by the base verb stop.","a2l20":"Life changes","a2rule20_1":"Present Perfect can announce a change relevant now. Past Simple gives the finished-time details of that change.","a2rule20_2":"Use get + adjective for a change, and be + adjective for a state. The form of get depends on the time: get, got or am/is/are getting.","a2rule20_3":"At first describes the beginning. In the end describes the final outcome. Because introduces a reason; so introduces the result.","a2g20":"Describe recent changes and finished events with clear time markers.","a2feedback20_1":"My life is singular: has + past participle changed.","a2feedback20_2":"Ago gives a finished past time: moved.","a2feedback20_3":"The past form of get is got.","a2feedback20_4":"With I, the continuous form uses am.","a2feedback20_5":"In the end describes the final outcome.","a2feedback20_6":"A finished time with ago takes Past Simple.","a2l21":"Working from home","a2rule21_1":"If + Present Simple can introduce a repeated situation with a present result. For a real future result, use will or another suitable modal in the main clause.","a2rule21_2":"May/might + base verb expresses uncertainty. Might not means possibly not; no do, to or -s is added. May can also express permission, so context matters.","a2rule21_3":"Future time clauses use a present form after when, before and as soon as. Put the future meaning in the main clause.","a2g21":"Discuss work routines, possible results and uncertain plans.","a2feedback21_1":"Will + base verb gives a real future result here.","a2feedback21_2":"Might takes the base verb take.","a2feedback21_3":"This future time clause uses Present Simple after when.","a2feedback21_4":"Use Present Simple in this real future if-clause.","a2feedback21_5":"Might not expresses a possible negative result.","a2feedback21_6":"Possibility uses might + base verb.","a2l22":"Learning a new job","a2rule22_1":"Past Simple uses a past form in statements. Questions and negatives use did/didn’t + base verb; be uses was/were instead.","a2rule22_2":"Show, give and send can use receiver + thing, or thing + to + receiver. Explain needs thing + to + receiver.","a2rule22_3":"Learn common do/make combinations: do a task or homework, but make a mistake or a list. Then/after that gives the next step; at the end of names the final part.","a2g22":"Describe completed tasks and explain who received help.","a2feedback22_1":"After did use the base verb do.","a2feedback22_2":"Explain takes the thing, then to + receiver.","a2feedback22_3":"Make a mistake is the usual combination.","a2feedback22_4":"The past form of write is wrote.","a2feedback22_5":"Send uses to for the receiver in this pattern.","a2feedback22_6":"Show can take receiver me before the thing the new system.","a2l23":"Job interview","a2rule23_1":"Use an auxiliary before the subject in most questions: do/does/did, be or a modal. After did, use the base verb.","a2rule23_2":"After Can you tell me or Do you know, an embedded question uses statement order. Yes/no questions use if or whether.","a2rule23_3":"Use can + base verb for abilities. After a preposition use -ing; want takes to + base verb.","a2g23":"Ask interview questions and describe abilities and strengths.","a2feedback23_1":"After did use the base verb like.","a2feedback23_2":"Inside the embedded question use subject + verb.","a2feedback23_3":"After can use the base verb type.","a2feedback23_4":"After at use -ing; both British and American spellings are valid.","a2feedback23_5":"Want takes to + base verb.","a2feedback23_6":"Present Simple question: do + subject + base verb.","a2l24":"My studies","a2rule24_1":"Some phrasal verbs are separable: write down and look up. A pronoun object must go in the middle.","a2rule24_2":"Other verbs stay together: look for, listen to and look forward to. After a preposition, use an object pronoun or an -ing form as appropriate.","a2rule24_3":"Use to + verb for purpose, but -ing after prepositions such as of and instead of.","a2g24":"Discuss study habits using phrasal verbs and learning patterns.","a2feedback24_1":"A pronoun goes between write and down.","a2feedback24_2":"Look up is separable; put it in the middle.","a2feedback24_3":"After the preposition of use -ing.","a2feedback24_4":"Listen to keeps the preposition before its object.","a2feedback24_5":"To + base verb gives the purpose of writing.","a2feedback24_6":"The to in look forward to is a preposition, so practising follows it.","a2l25":"Interview with an English Teacher","a2rule25_1":"Say can introduce a statement; tell needs a person. In past reporting, tenses often move back, but a still-true statement can keep its present tense.","a2rule25_2":"Reported questions use statement order. Use a question word, or if/whether for a yes/no question; do not keep do/does/did from the direct question.","a2rule25_3":"Report instructions with tell/ask + person + to + verb. A negative instruction uses not to + verb. Change pronouns to match the new speaker’s viewpoint.","a2g25":"Report statements, questions and simple instructions.","a2feedback25_1":"Tell needs a person: told me.","a2feedback25_2":"Reported questions use statement order and no did.","a2feedback25_3":"Tell + person + to-infinitive reports an instruction.","a2feedback25_4":"Reported yes/no questions use if or whether.","a2feedback25_5":"A negative reported instruction uses not to + verb.","a2feedback25_6":"Reported questions use subject I before verb studied.","a2l26":"Have you ever…?","a2rule26_1":"Have/Has + subject + ever + past participle asks about experience up to now. Answer with Yes, I have or No, I haven’t.","a2rule26_2":"Use Past Simple to ask when an experience happened or to give finished-time details.","a2rule26_3":"Learn irregular participles: eat → eaten, speak → spoken, break → broken. Never already has negative meaning; do not add haven’t to it.","a2g26":"Ask about life experiences and follow up with past details.","a2feedback26_1":"Present Perfect needs the participle broken.","a2feedback26_2":"Last year is a finished past time: left.","a2feedback26_3":"Never has negative meaning; use have + participle.","a2feedback26_4":"Speak has the past participle spoken.","a2feedback26_5":"Copy have from the Present Perfect question.","a2feedback26_6":"Experience question: have + subject + ever + participle.","a2l27":"At the Police Station: Stolen Phone","a2rule27_1":"Past Continuous uses was/were + -ing for an action in progress at a past moment. Past Simple describes a completed event.","a2rule27_2":"Use Past Continuous for the background and Past Simple for an event within it. While often introduces the background; the meaning matters more than the connector alone.","a2rule27_3":"Past Perfect uses had + past participle for an action earlier than another past point. Keep the later past reference clear.","a2g27":"Describe a past scene and identify an earlier past action.","a2feedback27_1":"Past Continuous uses was + buying.","a2feedback27_2":"The completed event uses bumped.","a2feedback27_3":"Earlier than left: had + participle checked.","a2feedback27_4":"With we, Past Continuous uses were + waiting.","a2feedback27_5":"After had use the participle locked.","a2feedback27_6":"The walk is background; noticed is the event during it.","a2l28":"If I were a millionaire","a2rule28_1":"Use if + Past Simple and would + base verb for an imaginary present or unlikely future. The past form does not mean past time here.","a2rule28_2":"If I were you is a common advice pattern. Were is usual in formal hypothetical clauses with I/he/she/it; was also occurs in everyday speech.","a2rule28_3":"Use wouldn’t for a negative result. Could or might can replace would for ability or possibility. Put a comma after an initial if-clause.","a2g28":"Describe imaginary situations using the Second Conditional.","a2feedback28_1":"The unreal condition uses a past form: had.","a2feedback28_2":"Advice about an imagined situation uses would + base verb.","a2feedback28_3":"After would/wouldn’t use the base verb stop.","a2feedback28_4":"If I were you is the usual advice expression.","a2feedback28_5":"Could expresses ability in the imaginary result.","a2feedback28_6":"Imaginary condition: if + past form, would + base verb.","a2l29":"How Our Family Life Has Changed","a2rule29_1":"Used to + base verb describes a past habit or state that is no longer true. Questions and negatives use did/didn’t + use to.","a2rule29_2":"Be/get used to + noun or -ing means being/becoming accustomed, not a past habit.","a2rule29_3":"Agree with a positive statement using So + auxiliary + subject, or too at the end. For a negative, use Neither + auxiliary + subject, or either at the end. These are adapted responses, not quotations from this audio.","a2g29":"Contrast past habits with life now and express agreement.","a2feedback29_1":"After did, use the base form use to.","a2feedback29_2":"The to in be used to is a preposition: getting.","a2feedback29_3":"Match be and invert: So am I.","a2feedback29_4":"Didn’t already marks the past: use to.","a2feedback29_5":"For a negative Present Simple statement use Neither do I.","a2feedback29_6":"Past habit: used to + base verb go.","a2l30":"Sports in the USA","a2rule30_1":"The passive uses be + past participle to focus on the receiver. Present: am/is/are + participle. Past: was/were + participle. These sports examples are adaptations.","a2rule30_2":"Defining clauses identify a person, thing or place without commas: who for people, which/that for things and where for the location of an action.","a2rule30_3":"Review by meaning: a routine uses Present Simple, an action now uses Present Continuous, and a finished past event uses Past Simple. Use Present Perfect for experience without a finished time; going to for an intention.","a2g30":"Describe sports with the passive and review time and relative clauses.","a2feedback30_1":"Present passive uses is + participle played.","a2feedback30_2":"Who identifies a person and is the clause subject.","a2feedback30_3":"Yesterday gives a finished past time: watched.","a2feedback30_4":"Singular game + past passive: was watched.","a2feedback30_5":"With we, the current action uses are + watching.","a2feedback30_6":"Experience question: have + subject + ever + participle.","a2listen":"Listen for the detail in the quoted transcript line."},"ru":{"module":"A2 · Повседневная жизнь","pilot":"A2 · 30 уроков · Грамматика, аудирование, словарь и разговорная практика.","moduleDone":"Все уроки A2 пройдены","a2l1":"Какие у тебя соседи по комнате?","a2l2":"Мои друзья","a2l3":"Моя семья","a2l4":"Помощь по дому","a2l5":"Город, в котором я живу","a2l6":"Как объяснить маршрут","a2l7":"Покупка одежды","a2l8":"Мои увлечения","a2l9":"Вечеринка в честь дня рождения","a2l10":"Разговор о фильмах","a2l11":"Заселение в отель","a2l12":"Аренда автомобиля","a2l13":"Транспорт в Нью-Йорке","a2l14":"Жизнь в Париже","a2l15":"Париж и Нью-Йорк: стоимость жизни","a2l16":"Достопримечательности Парижа","a2l17":"Американские бары","a2l18":"Планы на будущее","a2rule1_1":"С be ставьте глагол перед подлежащим. Для других глаголов в Present Simple используйте do/does + подлежащее + начальную форму.","a2rule1_2":"What is someone like? — вопрос о характере. What does someone like? — о предпочтениях.","a2rule1_3":"Present Simple описывает привычки, а Present Continuous — действие сейчас.","a2g1":"Задавайте вопросы о людях и различайте привычки и действия сейчас.","a2feedback1_1":"С be нужен обратный порядок: Are they friendly?","a2feedback1_2":"Mia — единственное число: does + начальная форма.","a2feedback1_3":"Be like спрашивает о характере; does like — о предпочтениях.","a2feedback1_4":"Привычка с she: studies.","a2feedback1_5":"Present Continuous: is + форма с -ing.","a2feedback1_6":"Порядок вопроса: Where + does + подлежащее + начальная форма.","a2rule2_1":"В вопросе к подлежащему спрашиваем, кто выполняет действие. В утвердительных вопросах простых времён do/does/did не нужны.","a2rule2_2":"В вопросе к дополнению сохраняется подлежащее; в простых временах используйте do/does/did + начальную форму.","a2rule2_3":"В обычной речи предлог часто ставится в конце вопроса.","a2g2":"Спрашивайте, кто выполняет действие и на кого оно направлено.","a2feedback2_1":"Who — подлежащее, поэтому listens без does.","a2feedback2_2":"Lisa остаётся подлежащим; после does нужна форма listen.","a2feedback2_3":"Сочетание go cycling with: with остаётся в конце.","a2feedback2_4":"Who — подлежащее; используйте форму loves.","a2feedback2_5":"После did нужна начальная форма meet.","a2feedback2_6":"В вопросе к дополнению about ставится в конце.","a2rule3_1":"Местоимение-подлежащее стоит перед глаголом; дополнение — после глагола или предлога.","a2rule3_2":"После притяжательного прилагательного нужно существительное. Притяжательное местоимение заменяет всю группу.","a2rule3_3":"Whose спрашивает о владельце. Its выражает принадлежность; it’s означает it is или it has.","a2g3":"Описывайте семью с помощью личных и притяжательных местоимений.","a2feedback3_1":"Получатель действия выражается формой me.","a2feedback3_2":"Перед существительным notebook нужна форма her.","a2feedback3_3":"Mine заменяет my notebook.","a2feedback3_4":"После предлога to нужна форма them.","a2feedback3_5":"Притяжательное its пишется без апострофа.","a2feedback3_6":"Whose спрашивает, кому принадлежит телефон.","a2rule4_1":"Must и have to выражают обязанность. Must часто передаёт требование говорящего, have to — необходимость; значения пересекаются.","a2rule4_2":"Mustn’t означает запрет. Don’t have to — отсутствие обязанности. Для обязанности в прошлом используйте had to.","a2rule4_3":"Запоминайте сочетания: do the dishes, do homework, make the bed, make a list.","a2g4":"Обсуждайте обязанности, запреты и необязательные дела по дому.","a2feedback4_1":"Mustn’t выражает запрет.","a2feedback4_2":"Don’t have to означает, что действие необязательно.","a2feedback4_3":"Make the bed — устойчивое сочетание.","a2feedback4_4":"Обязанность в прошлом выражается через had to.","a2feedback4_5":"С she используется has to.","a2feedback4_6":"В вопросах с have to: do + подлежащее + have to.","a2rule5_1":"Who уточняет людей, which/that — предметы. Если это подлежащее придаточного предложения, слово нельзя опускать.","a2rule5_2":"Where вводит место действия. В определительных придаточных этого типа запятые не нужны.","a2rule5_3":"Many используется с исчисляемыми существительными во множественном числе; much — с неисчисляемыми. A lot of подходит обоим типам.","a2g5":"Описывайте места с определительными придаточными и словами количества.","a2feedback5_1":"Where обозначает место, в котором происходит действие.","a2feedback5_2":"Who уточняет человека и является подлежащим придаточного предложения.","a2feedback5_3":"Traffic — неисчисляемое существительное: much.","a2feedback5_4":"Здесь возможны и that, и which; это дополнение придаточного предложения.","a2feedback5_5":"Parks — исчисляемое существительное во множественном числе: many.","a2feedback5_6":"Where вводит место действия; запятая в этом определительном придаточном не нужна.","a2rule6_1":"Along — вдоль улицы или пути; across — с одной стороны на другую; through — через внутреннюю часть пространства.","a2rule6_2":"To обозначает направление, into — вход внутрь. Go home/there употребляются без to. Для транспорта: by bus; пешком: on foot.","a2rule6_3":"Для занятий используйте go + -ing; также go for a walk и go on a trip.","a2g6":"Объясняйте маршрут с предлогами движения и сочетаниями с go.","a2feedback6_1":"Along обозначает движение вдоль линии, например улицы.","a2feedback6_2":"Into подчёркивает вход внутрь.","a2feedback6_3":"Для этого занятия используется go + -ing.","a2feedback6_4":"Home — наречие; предлог to не нужен.","a2feedback6_5":"Для способа передвижения используйте by bus без артикля.","a2feedback6_6":"Повелительное предложение начинается с начальной формы глагола turn.","a2rule7_1":"Something часто используется в утверждениях и предложениях; anything — в вопросах и отрицаниях. Прилагательное ставится после них.","a2rule7_2":"Too + прилагательное означает чрезмерность. Enough ставится перед существительным, но после прилагательного.","a2rule7_3":"Try on — разделяемый фразовый глагол. Местоимение-дополнение ставится между глаголом и частицей.","a2g7":"Покупайте одежду с помощью something/anything, too/enough и try on.","a2feedback7_1":"Для предмета используйте something; прилагательное warm ставится после него.","a2feedback7_2":"Перед прилагательным используется too, без much.","a2feedback7_3":"В разделяемом фразовом глаголе местоимение it ставится между глаголом и частицей.","a2feedback7_4":"Enough ставится после прилагательного big.","a2feedback7_5":"После didn’t используйте anything, чтобы избежать двойного отрицания в стандартном английском.","a2feedback7_6":"Прилагательное cheaper ставится после anything.","a2rule8_1":"После enjoy и предлогов используйте -ing. После like во многих случаях возможны -ing и to + глагол.","a2rule8_2":"После want, plan и would like обычно используется to + начальная форма. Цель действия также выражается через to + глагол.","a2rule8_3":"После модального глагола используйте начальную форму без to. Действие с -ing может быть подлежащим.","a2g8":"Рассказывайте об увлечениях с герундием и инфинитивом.","a2feedback8_1":"После enjoy используется форма с -ing.","a2feedback8_2":"После want используется инфинитив с to.","a2feedback8_3":"После can нужна начальная форма без to.","a2feedback8_4":"После предлога in используйте форму с -ing.","a2feedback8_5":"Действие в роли подлежащего можно выразить формой с -ing.","a2feedback8_6":"To learn выражает цель чтения.","a2rule9_1":"Past Simple описывает завершённые действия. В утверждении используется прошедшая форма; после did/didn’t — начальная.","a2rule9_2":"Because вводит причину с подлежащим и глаголом; because of — группу существительного. So вводит результат.","a2rule9_3":"Although вводит уступку. However обычно ставится после точки или точки с запятой; после него нужна запятая.","a2g9":"Рассказывайте о прошлом событии, связывая причины, результаты и противопоставления.","a2feedback9_1":"Last month — завершённое время в прошлом: went.","a2feedback9_2":"После didn’t нужна начальная форма stay.","a2feedback9_3":"The traffic — группа существительного: because of.","a2feedback9_4":"Although вводит уступку: несмотря на волнение, я получил удовольствие.","a2feedback9_5":"После did нужна начальная форма dance.","a2feedback9_6":"So связывает причину с результатом; эти части разделяются запятой.","a2rule10_1":"Для состояний и значений like, know, need, prefer обычно используйте простые формы.","a2rule10_2":"У некоторых глаголов форма зависит от значения: think как мнение — простая форма; thinking about — процесс размышления.","a2rule10_3":"Have в значении владения обычно имеет простую форму; have как действие может быть в Continuous.","a2g10":"Описывайте предпочтения в кино и различайте состояния и действия.","a2feedback10_1":"Think в значении мнения обычно используется в простой форме.","a2feedback10_2":"Have как действие, например приём пищи, может быть в Continuous.","a2feedback10_3":"Like в значении предпочтения обычно используется в Present Simple; с she нужно doesn’t.","a2feedback10_4":"Знание — состояние: I know.","a2feedback10_5":"Обдумывание выбора — действие: thinking about.","a2feedback10_6":"Prefer выражает предпочтение и обычно используется в простой форме.","a2rule11_1":"Can/Could + подлежащее + начальная форма выражает просьбу. Could здесь часто звучит вежливее, а не обозначает прошлое. После would like используется существительное или to + глагол.","a2rule11_2":"После give и show возможны получатель + предмет или предмет + to + получатель. Если оба дополнения — местоимения, обычно выбирайте предмет + to + получатель.","a2rule11_3":"После explain используйте предмет + to + человек, а не explain me. После buy получатель покупки вводится через for.","a2g11":"Вежливо обращайтесь в отеле и передавайте что-то кому-то.","a2feedback11_1":"После could: подлежащее + начальная форма, без do и to.","a2feedback11_2":"Местоимение-предмет it ставится перед to + получатель me.","a2feedback11_3":"После explain нужен предмет + to + получатель.","a2feedback11_4":"После would like перед глаголом используется to.","a2feedback11_5":"После buy получатель покупки вводится через for.","a2feedback11_6":"После show получатель me может стоять перед предметом the room.","a2rule12_1":"Present Continuous может описывать будущую договорённость. Going to + начальная форма выражает намерение и также может описывать согласованный план.","a2rule12_2":"By + время означает не позднее этого времени. At + время указывает конкретный момент.","a2rule12_3":"On time — вовремя по расписанию. In time — достаточно рано, чтобы успеть что-то сделать. Оба выражения могут описывать одно прибытие.","a2g12":"Обсуждайте планы поездок, крайние сроки и прибытие вовремя.","a2feedback12_1":"Present Continuous образуется через am + meeting; tomorrow указывает на будущий контекст.","a2feedback12_2":"By обозначает крайний срок, а не точное время встречи.","a2feedback12_3":"In time означает достаточно рано; on time — вовремя по расписанию.","a2feedback12_4":"С I используется am going to + начальная форма.","a2feedback12_5":"С we используется are + driving для этого будущего плана.","a2feedback12_6":"In time to + глагол означает достаточно рано, чтобы успеть выполнить действие.","a2rule13_1":"Со многими короткими прилагательными используйте -er, с длинными — more. Сравнивайте через than; good → better, bad → worse.","a2rule13_2":"Для сравнения одного варианта со всей группой используйте the best, the fastest, the most comfortable. Не сочетайте more с -er или most с -est.","a2rule13_3":"Most + существительное — большинство в целом. Most of + these/the/my или объектное местоимение — большинство конкретной группы; the most может выражать превосходную степень.","a2g13":"Сравнивайте транспорт и различайте most и most of.","a2feedback13_1":"Перед than используйте сравнительную степень cheaper.","a2feedback13_2":"Good имеет неправильную превосходную степень the best.","a2feedback13_3":"These указывает на конкретную группу: most of.","a2feedback13_4":"Сравнительная степень bad — worse.","a2feedback13_5":"Перед объектным местоимением: most of us.","a2feedback13_6":"Сравнительная степень + than вводит второй вариант.","a2rule14_1":"Present Simple описывает привычки. Present Continuous — действия сейчас и временные ситуации в текущий период.","a2rule14_2":"Get + прилагательное описывает изменение. Getting используется для изменения в процессе.","a2rule14_3":"No longer обычно ставится перед основным глаголом или после be. Anymore/any longer — в конце отрицательного предложения; any more также допустимо в значении времени, особенно в британском английском.","a2g14":"Описывайте привычки, изменения и прекратившиеся действия.","a2feedback14_1":"Привычка выражается через Present Simple; с Emma используется writes.","a2feedback14_2":"Present Continuous: is + looking.","a2feedback14_3":"No longer ставится перед feel и уже даёт отрицательное значение.","a2feedback14_4":"Get + прилагательное обозначает изменение; в getting удваивается t.","a2feedback14_5":"Эти выражения в конце предложения означают прекращение ситуации; any more в значении времени тоже допустимо.","a2feedback14_6":"Is getting + сравнительная степень описывает улучшение в процессе.","a2rule15_1":"Present Perfect образуется через have/has + третью форму. Оно связывает прошлое с настоящим: опыт и ситуации, продолжающиеся сейчас.","a2rule15_2":"Для завершённых прошлых периодов используйте Past Simple. Для ситуации, начавшейся раньше и продолжающейся сейчас, — Present Perfect; не добавляйте yesterday или завершённую прошлую дату.","a2rule15_3":"For вводит длительность; since — начальную точку. Сравнительную степень можно усилить через much или a lot.","a2g15":"Различайте завершённое прошлое и ситуации, продолжающиеся сейчас.","a2feedback15_1":"Ситуация продолжается сейчас: have lived.","a2feedback15_2":"Этот период завершён: Past Simple.","a2feedback15_3":"Much усиливает сравнительную степень; more перед cheaper не нужно.","a2feedback15_4":"Six months — длительность: for.","a2feedback15_5":"Monday — начальная точка: since.","a2feedback15_6":"Have + третья форма lived образует Present Perfect; for вводит длительность.","a2rule16_1":"Для совета используйте should + начальную форму. Shouldn’t — совет не делать что-то; to и окончание -s не нужны.","a2rule16_2":"Вопрос: Should + подлежащее + начальная форма, без do. I think you should и I don’t think you should выражают личную рекомендацию.","a2rule16_3":"Реальное условие можно выразить через if + Present Simple, а результат — повелительной формой или can. Когда часть с if стоит первой, нужна запятая.","a2g16":"Давайте советы о достопримечательностях через should и условные предложения.","a2feedback16_1":"После should нужна начальная форма wear.","a2feedback16_2":"Should ставится перед подлежащим, без do и to.","a2feedback16_3":"В этом реальном будущем условии после if используется Present Simple.","a2feedback16_4":"Shouldn’t или should not выражает совет не спешить.","a2feedback16_5":"Can + начальная форма выражает возможность при этом условии.","a2feedback16_6":"Совет: подлежащее + should + начальная форма.","a2rule17_1":"Цель действия выражается через to + начальную форму; предмет или занятие — через for + существительное. For + -ing может описывать функцию предмета.","a2rule17_2":"Must выражает строгое требование; should — совет. После обоих нужна начальная форма без to; форма одинакова для всех лиц.","a2rule17_3":"Mustn’t означает запрет. Don’t/doesn’t have to — необязательность, а не запрет. В вопросах с have to используются do/does.","a2g17":"Объясняйте цель и различайте советы, правила и необязательные действия.","a2feedback17_1":"Для цели встречи используйте to + начальную форму.","a2feedback17_2":"После for используется группа существительного a chat.","a2feedback17_3":"Don’t have to означает отсутствие обязанности.","a2feedback17_4":"For + -ing описывает функцию экрана.","a2feedback17_5":"Вопрос с have to: do + подлежащее + have to.","a2feedback17_6":"После must нужна начальная форма без to.","a2rule18_1":"Для намерения используйте am/is/are + going to + начальную форму. Not ставится после be; в вопросе be — перед подлежащим.","a2rule18_2":"Will часто выражает решение в момент речи или предложение помощи. Going to — ранее принятое намерение; Present Continuous — договорённость. Эти формы будущего иногда пересекаются.","a2rule18_3":"После want, plan и would like используется to + начальная форма. Planning описывает намерение или планирование; само по себе оно не означает, что поездка уже забронирована.","a2g18":"Обсуждайте намерения, желания и решения о будущем.","a2feedback18_1":"С I используется am going to + начальная форма.","a2feedback18_2":"I’ll help you — предложение помощи в момент речи.","a2feedback18_3":"После would like используется инфинитив с to.","a2feedback18_4":"С she используется is going to.","a2feedback18_5":"После plan нужен to + глагол; planning само по себе не подтверждает бронирование.","a2feedback18_6":"Намерение: подлежащее + am + going to + начальная форма.","a2l19":"Новогодние обещания","a2rule19_1":"Going to описывает намерение. В отрицании not ставится после am/is/are, перед going to.","a2rule19_2":"A few используется с исчисляемыми существительными во множественном числе; a little — с неисчисляемыми. Они означают некоторое количество; few/little без a часто подразумевают недостаток.","a2rule19_3":"Less — меньшее количество с неисчисляемым существительным; fewer — меньшее число с исчисляемым во множественном числе. Too much/too many означает чрезмерное количество.","a2g19":"Описывайте намерения и посильный объём практики.","a2feedback19_1":"Not ставится после am, перед going to.","a2feedback19_2":"Goals — исчисляемое существительное во множественном числе: a few.","a2feedback19_3":"Time — неисчисляемое: less.","a2feedback19_4":"Time — неисчисляемое: a little time.","a2feedback19_5":"Distractions — исчисляемое во множественном числе: too many.","a2feedback19_6":"Not идёт после am; после going to нужна начальная форма stop.","a2l20":"Перемены в жизни","a2rule20_1":"Present Perfect может сообщать о перемене, важной сейчас. Past Simple передаёт подробности с завершённым временем.","a2rule20_2":"Для изменения используйте get + прилагательное, для состояния — be + прилагательное. Форма get зависит от времени: get, got или am/is/are getting.","a2rule20_3":"At first описывает начало; in the end — итог. Because вводит причину, so — результат.","a2g20":"Описывайте недавние перемены и завершённые события с указанием времени.","a2feedback20_1":"My life — единственное число: has + третья форма changed.","a2feedback20_2":"Ago указывает завершённое прошлое: moved.","a2feedback20_3":"Прошедшая форма get — got.","a2feedback20_4":"С I в Continuous используется am.","a2feedback20_5":"In the end описывает итог.","a2feedback20_6":"Завершённое время с ago требует Past Simple.","a2l21":"Работа из дома","a2rule21_1":"If + Present Simple может вводить повторяющуюся ситуацию с результатом в настоящем. Для реального будущего результата используйте will или другой подходящий модальный глагол в главной части.","a2rule21_2":"May/might + начальная форма выражает неопределённость. Might not — возможно, не; do, to и -s не добавляются. May также выражает разрешение, поэтому важен контекст.","a2rule21_3":"В придаточных времени о будущем после when, before и as soon as используется форма настоящего. Значение будущего передаётся главной частью.","a2g21":"Обсуждайте рабочие привычки, возможные результаты и неопределённые планы.","a2feedback21_1":"Will + начальная форма выражает здесь реальный будущий результат.","a2feedback21_2":"После might нужна начальная форма take.","a2feedback21_3":"В этом придаточном времени о будущем после when используется Present Simple.","a2feedback21_4":"В этом реальном условии о будущем используется Present Simple.","a2feedback21_5":"Might not выражает возможный отрицательный результат.","a2feedback21_6":"Возможность: might + начальная форма.","a2l22":"Освоение новой работы","a2rule22_1":"В Past Simple утверждение содержит прошедшую форму. В вопросах и отрицаниях используется did/didn’t + начальная форма; для be — was/were.","a2rule22_2":"Show, give и send допускают получатель + предмет или предмет + to + получатель. Explain требует предмет + to + получатель.","a2rule22_3":"Запоминайте сочетания: do a task/homework, но make a mistake/list. Then/after that вводит следующий шаг; at the end of — заключительную часть.","a2g22":"Описывайте выполненные задачи и уточняйте, кому помогли.","a2feedback22_1":"После did нужна начальная форма do.","a2feedback22_2":"После explain: предмет, затем to + получатель.","a2feedback22_3":"Обычное сочетание: make a mistake.","a2feedback22_4":"Прошедшая форма write — wrote.","a2feedback22_5":"Send в этом порядке использует to перед получателем.","a2feedback22_6":"После show получатель me может стоять перед предметом the new system.","a2l23":"Собеседование","a2rule23_1":"В большинстве вопросов вспомогательный глагол стоит перед подлежащим: do/does/did, be или модальный. После did нужна начальная форма.","a2rule23_2":"После Can you tell me или Do you know вложенный вопрос использует порядок утверждения. Для вопроса да/нет используется if или whether.","a2rule23_3":"Для способностей используйте can + начальную форму. После предлога нужна форма -ing; после want — to + начальная форма.","a2g23":"Задавайте вопросы на собеседовании и описывайте способности и сильные стороны.","a2feedback23_1":"После did нужна начальная форма like.","a2feedback23_2":"Во вложенном вопросе используется подлежащее + глагол.","a2feedback23_3":"После can нужна начальная форма type.","a2feedback23_4":"После at используется -ing; допустимы британское и американское написания.","a2feedback23_5":"После want нужен to + начальная форма.","a2feedback23_6":"Вопрос Present Simple: do + подлежащее + начальная форма.","a2l24":"Моя учёба","a2rule24_1":"Некоторые фразовые глаголы разделяются: write down и look up. Местоимение-дополнение обязательно ставится между частями.","a2rule24_2":"Другие сочетания остаются вместе: look for, listen to и look forward to. После предлога используются объектное местоимение или форма -ing в зависимости от конструкции.","a2rule24_3":"Для цели используйте to + глагол; после предлогов of и instead of — форму -ing.","a2g24":"Обсуждайте учёбу с фразовыми глаголами и сочетаниями для обучения.","a2feedback24_1":"Местоимение ставится между write и down.","a2feedback24_2":"Look up разделяется; it ставится между частями.","a2feedback24_3":"После предлога of нужна форма -ing.","a2feedback24_4":"В listen to предлог стоит перед дополнением.","a2feedback24_5":"To + начальная форма выражает цель записи.","a2feedback24_6":"To в look forward to — предлог, поэтому после него practising.","a2l25":"Интервью с преподавателем английского","a2rule25_1":"Say вводит утверждение; tell требует указания человека. При сообщении из прошлого времена часто сдвигаются назад, но актуальное утверждение может сохранить настоящее время.","a2rule25_2":"В косвенных вопросах используется порядок утверждения. Нужны вопросительное слово либо if/whether для вопроса да/нет; do/does/did из прямого вопроса не сохраняются.","a2rule25_3":"Передавайте инструкции через tell/ask + человек + to + глагол. Отрицательная инструкция: not to + глагол. Местоимения меняются с учётом точки зрения говорящего.","a2g25":"Передавайте утверждения, вопросы и простые инструкции в косвенной речи.","a2feedback25_1":"Tell требует человека: told me.","a2feedback25_2":"В косвенном вопросе используется порядок утверждения без did.","a2feedback25_3":"Инструкция: tell + человек + инфинитив с to.","a2feedback25_4":"Косвенные вопросы да/нет вводятся через if или whether.","a2feedback25_5":"Отрицательная инструкция в косвенной речи: not to + глагол.","a2feedback25_6":"В косвенном вопросе подлежащее I стоит перед studied.","a2l26":"Ты когда-нибудь…?","a2rule26_1":"Have/Has + подлежащее + ever + третья форма спрашивает об опыте до настоящего момента. Краткий ответ: Yes, I have или No, I haven’t.","a2rule26_2":"Используйте Past Simple, чтобы спросить, когда произошёл случай, или сообщить подробности с завершённым временем.","a2rule26_3":"Запоминайте неправильные третьи формы: eat → eaten, speak → spoken, break → broken. Never уже имеет отрицательное значение; haven’t к нему не добавляется.","a2g26":"Спрашивайте о жизненном опыте и уточняйте подробности в прошлом.","a2feedback26_1":"Для Present Perfect нужна третья форма broken.","a2feedback26_2":"Last year — завершённое прошлое: left.","a2feedback26_3":"Never уже выражает отрицание; используйте have + третью форму.","a2feedback26_4":"Третья форма speak — spoken.","a2feedback26_5":"В кратком ответе повторяется have из вопроса.","a2feedback26_6":"Вопрос об опыте: have + подлежащее + ever + третья форма.","a2l27":"Украденный телефон","a2rule27_1":"Past Continuous: was/were + -ing для действия в процессе в прошлый момент. Past Simple описывает завершённое событие.","a2rule27_2":"Past Continuous описывает фон, Past Simple — событие на этом фоне. While часто вводит фон; важен смысл, а не только союз.","a2rule27_3":"Past Perfect: had + третья форма для действия раньше другого момента в прошлом. Указывайте понятный более поздний ориентир.","a2g27":"Описывайте ситуацию в прошлом и действие, произошедшее ещё раньше.","a2feedback27_1":"Past Continuous: was + buying.","a2feedback27_2":"Завершённое событие выражается формой bumped.","a2feedback27_3":"Действие раньше left: had + третья форма checked.","a2feedback27_4":"С we в Past Continuous используется were + waiting.","a2feedback27_5":"После had нужна третья форма locked.","a2feedback27_6":"Ходьба — фон, noticed — событие на этом фоне.","a2l28":"Если бы я был миллионером","a2rule28_1":"Для воображаемого настоящего или маловероятного будущего: if + Past Simple и would + начальная форма. Прошедшая форма здесь не означает прошедшее время.","a2rule28_2":"If I were you — распространённая формула совета. Were обычно используется в формальных гипотетических предложениях с I/he/she/it; was тоже встречается в повседневной речи.","a2rule28_3":"Для отрицательного результата используйте wouldn’t. Could или might заменяют would для способности или возможности. После начальной части с if нужна запятая.","a2g28":"Описывайте воображаемые ситуации через Second Conditional.","a2feedback28_1":"Нереальное условие использует прошедшую форму had.","a2feedback28_2":"Совет в воображаемой ситуации: would + начальная форма.","a2feedback28_3":"После would/wouldn’t нужна начальная форма stop.","a2feedback28_4":"Обычная формула совета: If I were you.","a2feedback28_5":"Could выражает возможность в воображаемом результате.","a2feedback28_6":"Воображаемое условие: if + прошедшая форма, would + начальная форма.","a2l29":"Как изменилась семейная жизнь","a2rule29_1":"Used to + начальная форма описывает прошлую привычку или состояние, которые больше не актуальны. Вопросы и отрицания: did/didn’t + use to.","a2rule29_2":"Be/get used to + существительное или -ing означает привыкнуть или быть привычным к чему-то, а не прошлую привычку.","a2rule29_3":"Для согласия с утверждением: So + вспомогательный глагол + подлежащее или too в конце. С отрицанием: Neither + вспомогательный глагол + подлежащее или either в конце. Это учебные ответы, а не цитаты из аудио.","a2g29":"Сравнивайте прошлые привычки с настоящим и выражайте согласие.","a2feedback29_1":"После did используется начальная форма use to.","a2feedback29_2":"To в be used to — предлог: getting.","a2feedback29_3":"Повторите be и используйте обратный порядок: So am I.","a2feedback29_4":"Didn’t уже отмечает прошлое: use to.","a2feedback29_5":"Для отрицательного Present Simple: Neither do I.","a2feedback29_6":"Прошлая привычка: used to + начальная форма go.","a2l30":"Спорт в США — итоговое повторение","a2rule30_1":"Пассив: be + третья форма, внимание на получателе действия. Настоящее: am/is/are + третья форма; прошлое: was/were + третья форма. Эти примеры о спорте адаптированы для обучения.","a2rule30_2":"Определительные придаточные уточняют человека, предмет или место без запятых: who для людей, which/that для предметов, where для места действия.","a2rule30_3":"Повторяйте по смыслу: привычка — Present Simple, действие сейчас — Present Continuous, завершённое прошлое — Past Simple. Опыт без завершённого времени — Present Perfect; намерение — going to.","a2g30":"Описывайте спорт через пассив и повторяйте времена и определительные придаточные.","a2feedback30_1":"Пассив настоящего: is + третья форма played.","a2feedback30_2":"Who уточняет человека и является подлежащим придаточного.","a2feedback30_3":"Yesterday — завершённое прошлое: watched.","a2feedback30_4":"Game — единственное число; пассив прошлого: was watched.","a2feedback30_5":"С we для действия сейчас используется are + watching.","a2feedback30_6":"Вопрос об опыте: have + подлежащее + ever + третья форма.","a2listen":"Ищите нужную деталь в приведённой строке транскрипции."}};const I=root.EvoCourseI18n;for(const code of Object.keys(I.ui)){I.ui[code].module=extra.en.module;I.ui[code].pilot=extra.en.pilot;I.ui[code].moduleDone=extra.en.moduleDone;}for(const [code,values] of Object.entries(extra))Object.assign(I.ui[code],values);if(typeof module==='object'&&module.exports)module.exports=extra;})(typeof globalThis==='object'?globalThis:this);
